config_templates.nginx.conf:
worker_processes 1;
pid {{run}}/nginx.pid;
error_log {{logs}}/nginx-{{version}}-error.log warn;

events {
    worker_connections 1024;
}

http {
    types {
        text/html html htm;
        text/css css;
        text/plain txt;
        application/javascript js mjs;
        application/json json;
        application/wasm wasm;
        application/pdf pdf;
        image/png png;
        image/jpeg jpg jpeg;
        image/gif gif;
        image/svg+xml svg;
        image/webp webp;
        image/avif avif;
        image/x-icon ico;
        font/woff woff;
        font/woff2 woff2;
    }
    default_type application/octet-stream;
    sendfile on;
    access_log {{logs}}/nginx-{{version}}-access.log;

    client_body_temp_path {{run}}/client_body;
    proxy_temp_path {{run}}/proxy;
    fastcgi_temp_path {{run}}/fastcgi;
    uwsgi_temp_path {{run}}/uwsgi;
    scgi_temp_path {{run}}/scgi;

    server {
        listen 127.0.0.1:{{port}};
        server_name localhost;
        root {{www}};
        index index.html index.htm;

        location / {
            try_files $uri $uri/ =404;
        }
    }

    # Projects (<folder>.test) generated by CheesEnv, plus your own *.conf files.
    include "{{conf}}/vhosts/*.conf";
}
